            var requestDescriptor = ExactDescriptor(authority["request"]);
            var resultDescriptor = ExactDescriptor(authority["result"]);
            var request = Read(requestDescriptor, 1024 * 1024);
            var result = Read(resultDescriptor, 16 * 1024 * 1024);
