                (int?)request["schema_version"] != 1 ||
                (string)request["catalog_id"] != (string)initialization["mission_id"] ||
                !JToken.DeepEquals(request["resource_preset"], presetDescriptor) ||
                (string)result["kind"] != "SkirmishMissionAuthoringPreflightResult" ||
                (int?)result["schema_version"] != 1 ||
                (string)result["status"] != "ConfigurationCompiled" ||
                (bool?)result["compiler_accepted"] != true ||
                (bool?)result["world_allocated"] != false ||
                (bool?)result["source_fit_verified"] != false ||
                (bool?)result["mission_ready"] != false ||
                (bool?)result["native_acceptance"] != false ||
                (string)result["catalog_id"] != (string)request["catalog_id"] ||
                setup == null || (string)result["catalog_id"] != setup.CatalogId ||
                (long?)result["resolved_setup"]?["setup_hash"] != (long)setup.SetupHash)
                throw new InvalidDataException("Exact compiler-selected resource-preset authoring join required");

            var pins = result["input_pins"] as JObject;
            var requestPath = Path.GetFullPath((string)requestDescriptor["path"]);
            var presetPath = Path.GetFullPath((string)presetDescriptor["path"]);
            if (pins == null || pins.Count < 1 || pins.Count > 8192 ||
                !PinMatches(pins, requestPath, (string)requestDescriptor["sha256"]) ||
                !PinMatches(pins, presetPath, (string)presetDescriptor["sha256"]))
                throw new InvalidDataException("Compiler result does not pin the exact request and resource preset");
        }

        static bool PinMatches(JObject pins, string path, string sha)
        {
            var value = pins[path] as JObject;
            return value != null && (string)value["sha256"] == sha;
        }

        static JObject ExactDescriptor(JToken token)
        {
            var value = token as JObject;
            if (value == null || value.Count != 2 || value.Properties().Any(p => p.Name != "path" && p.Name != "sha256") ||
                value["path"]?.Type != JTokenType.String || value["sha256"]?.Type != JTokenType.String ||
                !Path.IsPathFullyQualified((string)value["path"]) || !IsSha256((string)value["sha256"]))
                throw new InvalidDataException("Exact absolute resource-preset authoring descriptor required");
            return value;
        }

        static void ExactKeys(JObject value, params string[] names)
        {
            if (value == null || value.Count != names.Length || value.Properties().Any(p => !names.Contains(p.Name, StringComparer.Ordinal)))
                throw new InvalidDataException("Exact resource-preset authoring linkage required");
        }

        static JObject Read(JObject descriptor, int maximum)
        {
            var raw = AutonomousWorld.PinnedFile((string)descriptor["path"], (string)descriptor["sha256"], maximum);
            using var reader = new JsonTextReader(new StringReader(Encoding.UTF8.GetString(raw))) { DateParseHandling = DateParseHandling.None };
            var value = JObject.Load(reader, new JsonLoadSettings { DuplicatePropertyNameHandling = DuplicatePropertyNameHandling.Error });
            if (reader.Read()) throw new InvalidDataException("One complete resource-preset authoring document required");
            return value;
        }

        static bool IsSha256(string value) => value != null && value.Length == 64 && value.All(c => c >= '0' && c <= '9' || c >= 'a' && c <= 'f');
    }
}
